def backfill_group_number(apps, schema_editor):
    """
    The one real run executed before this migration (S040, 3.570
    grupos) has every line at group_number=0 by default -- this
    reconstructs the real grouping from creation order: bulk_create
    wrote KEPT then its TRASHED siblings, KEPT then its TRASHED
    siblings..., in exactly that sequence (see
    ResolveDuplicatesView.post -- log_lines is built the same way), so
    ordering by id and starting a new group at every KEPT recovers the
    original grouping without guessing.

    Also backfills `crc32c` best-effort from `index_entry` where that
    row hasn't been purged yet -- rows created before this migration
    never had `crc32c` captured at all.
    """
    DataOperationLogEntry = apps.get_model(
        "document_explorer", "DataOperationLogEntry",
    )
    DataOperationLog = apps.get_model(
        "document_explorer", "DataOperationLog",
    )
    for log in DataOperationLog.objects.all():
        group_number = 0
        rows = []
        for entry in log.entries.select_related("index_entry").order_by("id"):
            if entry.action == "KEPT":
                group_number += 1
            entry.group_number = group_number
            if not entry.crc32c and entry.index_entry_id:
                entry.crc32c = entry.index_entry.crc32c
            rows.append(entry)
        if rows:
            DataOperationLogEntry.objects.bulk_update(
                rows, ["group_number", "crc32c"],
            )


